const php = (v: View): string => {
  const pending = { ...v, readOnly: true }
  const accounts = (v.props.accounts ?? []).map(account => [account.username, c(account.username, account.username)] as const)
  const versionActions = `<div class="xp-whm-detail-fields">${field(pending, 'php-selected-version', c('Selected version', 'الإصدار المحدد'), { choices: [] })}${field(pending, 'php-install-version', c('Version to install', 'الإصدار المطلوب تثبيته'))}</div>${actions(button(pending, c('Set as default', 'تعيين كافتراضي')) + button(pending, c('Reinstall selected version', 'إعادة تثبيت الإصدار المحدد')) + button(pending, c('Remove selected version', 'حذف الإصدار المحدد')))}<details><summary>${v.text(c('Confirm version removal', 'تأكيد حذف الإصدار'))}</summary>${status(v, c('No installed version or dependent-domain inventory has been read. A version cannot be removed while affected domains and handlers are unknown.', 'لم يُقرأ جرد الإصدارات المثبتة أو النطاقات المعتمدة عليها. لا يمكن حذف إصدار قبل معرفة النطاقات والمعالجات المتأثرة.'))}${actions(button(pending, c('Remove version', 'حذف الإصدار')) + button(pending, c('Cancel', 'إلغاء')))}</details>`
  const extensions = `<div class="xp-whm-detail-fields">${field(pending, 'php-extension-version', c('Extensions for PHP version', 'امتدادات إصدار PHP'), { choices: [] })}</div>${table(v, c('Extensions per version', 'الامتدادات لكل إصدار'), [c('Extension', 'الامتداد'), c('Version', 'الإصدار'), c('Enabled', 'مفعّل'), c('State', 'الحالة')], [])}<div class="xp-whm-detail-choice-grid">${['curl', 'gd', 'intl', 'mbstring', 'mysqli', 'opcache', 'pdo_mysql', 'zip'].map(name => choice(pending, `php-extension-${name}`, c(name, name), undefined)).join('')}</div>${status(v, c('Extension inventory and per-version enablement have not been read. These controls do not claim the packages are installed or enabled.', 'لم يُقرأ جرد الامتدادات أو تفعيلها لكل إصدار. لا تعني هذه الأدوات أن الحزم مثبتة أو مفعّلة.'))}`
  const configuration = `<div class="xp-whm-detail-fields">${field(pending, 'php-version', c('Version', 'الإصدار'), { choices: [] })}${field(pending, 'memory_limit', c('memory_limit', 'memory_limit'))}${field(pending, 'upload_max_filesize', c('upload_max_filesize', 'upload_max_filesize'))}${field(pending, 'post_max_size', c('post_max_size', 'post_max_size'))}${field(pending, 'max_execution_time', c('max_execution_time', 'max_execution_time'))}${field(pending, 'max_input_vars', c('max_input_vars', 'max_input_vars'))}</div><details><summary>php.ini</summary>${field(pending, 'php-ini', c('File contents', 'محتوى الملف'), { type: 'textarea' })}</details>${actions(button(pending, c('Common settings', 'الإعدادات الشائعة')) + button(pending, c('Edit file', 'تحرير الملف')) + button(pending, c('Discard', 'تجاهل')) + button(pending, c('Test and apply', 'الفحص والتطبيق'), '', false, true))}${status(v)}`
  const exceptions = `${table(v, c('Function exceptions', 'استثناءات الدوال'), [c('Account', 'الحساب'), c('Functions', 'الدوال'), c('Reason', 'السبب'), c('Action', 'الإجراء')], [])}${actions(button(pending, c('Add exception', 'إضافة استثناء')))}<details><summary>${v.text(c('New exception', 'استثناء جديد'))}</summary><div class="xp-whm-detail-fields">${field(pending, 'php-exception-account', c('Account', 'الحساب'), { choices: accounts })}${field(pending, 'php-exception-reason', c('Reason', 'السبب'), { type: 'textarea' })}</div><h3>${v.text(c('Allow these functions', 'السماح بهذه الدوال'))}</h3><div class="xp-whm-detail-choice-grid">${['exec', 'shell_exec', 'system', 'passthru', 'proc_open', 'popen'].map(name => choice(pending, `php-exception-${name}`, c(name, name), undefined)).join('')}</div>${actions(button(pending, c('Grant exception', 'منح استثناء'), '', false, true) + button(pending, c('Cancel', 'إلغاء')))}</details>${actions(button(pending, c('Revoke', 'إلغاء الاستثناء')) + button(pending, c('Undo', 'تراجع')))}${status(v, c('The global function policy and saved exceptions have not been read; grant, revoke and undo have no connected global policy API.', 'لم تُقرأ سياسة الدوال العامة أو الاستثناءات المحفوظة؛ ولا توجد واجهة موصولة لمنح الاستثناءات العامة أو إلغائها أو التراجع عنها.'))}`
  return workspace(v, '/whm/software/php', c('PHP versions and handlers', 'إصدارات PHP والمعالجات'), c('Version inventory, engine compatibility, extensions and global defaults.', 'جرد الإصدارات وتوافق المحرك والامتدادات والقيم العامة الافتراضية.'),
    card(v, 'php-versions', c('Installed versions', 'الإصدارات المثبتة'), `${table(v, c('Installed PHP versions', 'إصدارات PHP المثبتة'), [c('Version', 'الإصدار'), c('Default', 'الافتراضي'), c('State', 'الحالة')], [])}${status(v, c('The installed PHP inventory has not been read. A domain’s desired PHP version does not establish that the package is installed.', 'لم يُقرأ جرد PHP المثبت. لا يثبت إصدار PHP المطلوب لنطاق أن الحزمة مثبتة.'))}${versionActions}`)
    + card(v, 'php-install', c('Install another version', 'تثبيت إصدار آخر'), field(pending, 'php-install-request', c('Package version', 'إصدار الحزمة')) + actions(button(pending, c('Install selected PHP version', 'تثبيت إصدار PHP المحدد'), '', false, true)) + status(v, c('Available package versions and repositories have not been read. No package installation or removal has started.', 'لم تُقرأ إصدارات الحزم المتاحة أو مستودعاتها. لم يبدأ تثبيت حزمة أو حذفها.')))
    + card(v, 'php-extensions', c('Extensions per version', 'الامتدادات لكل إصدار'), extensions)
    + card(v, 'php-configure', c('Configure a version', 'إعداد إصدار'), configuration),
    card(v, 'php-handlers', c('Handlers', 'المعالجات'), table(v, c('PHP handler compatibility', 'توافق معالجات PHP'), [c('Handler', 'المعالج'), c('Engine', 'المحرك'), c('Identity', 'الهوية'), c('Availability', 'التوافر')], [['PHP-FPM', 'Apache', v.text(c('Per-account pool', 'مجموعة لكل حساب')), v.text(unavailable)], ['CGI / suexec', 'Apache', v.text(c('Account UID', 'هوية الحساب')), v.text(unavailable)], ['lsphp', 'OpenLiteSpeed', v.text(c('Account external app', 'تطبيق خارجي للحساب')), v.text(unavailable)]]))
    + card(v, 'php-functions', c('Dangerous functions', 'الدوال الخطرة'), exceptions))
}

const setup = (v: View): string => {
  const s = v.props.serverSettings
  const workersView = { ...v, readOnly: v.readOnly || !s }
  const primaryIpv4 = v.props.ipPool?.find(ip => ip.isPrimary && ip.version === 4)?.address
  const identity = `<ol class="xp-whm-detail-steps" aria-label="${v.text(c('Setup steps', 'خطوات الإعداد'))}">${[c('Host and nameservers', 'المضيف وخوادم الأسماء'), c('Engine and workers', 'المحرك والعمليات'), c('Review', 'المراجعة'), c('Apply', 'التطبيق')].map((step, i) => `<li><strong>${i + 1}</strong><span>${v.text(step)}</span></li>`).join('')}</ol>${form(v, 'setup-wizard-form', `<div class="xp-whm-detail-fields">${field(v, 'hostname', c('Server hostname', 'اسم مضيف الخادم'), { value: s?.hostname })}${field(v, 'adminEmail', c('Admin email', 'بريد المدير'), { value: s?.adminEmail, type: 'email' })}${field(v, 'primaryIpv4', c('Primary IPv4 address', 'عنوان IPv4 الأساسي'), { value: primaryIpv4, required: true, help: c('Use the actual primary IPv4 assigned to this server. No address is generated or assumed.', 'استخدم عنوان IPv4 الأساسي المعيّن فعليًا لهذا الخادم. لا يُولّد عنوان أو يُفترض.') })}${field(v, 'engine', c('Web engine', 'محرك الويب'), { value: s?.engine, choices: engineChoices })}${field(v, 'apacheMpm', c('Apache MPM', 'Apache MPM'), { value: s?.apacheMpm, choices: mpmChoices })}${field(v, 'panelPort', c('Panel port', 'منفذ اللوحة'), { value: s?.panelPort, type: 'number' })}${field(v, 'sshPort', c('SSH port', 'منفذ SSH'), { value: s?.sshPort, type: 'number' })}</div>${field(v, 'nameservers', c('Nameservers, one per line', 'خوادم الأسماء، واحد في كل سطر'), { value: s?.nameservers.join('\n'), type: 'textarea' })}${field(v, 'quotaFilesystem', c('Quota filesystem', 'نظام ملفات الحصة'), { help: c('A path alone does not establish that quotas are enabled.', 'لا يثبت المسار وحده أن الحصص مفعّلة.') })}${actions(save(v, c('Review setup', 'مراجعة الإعداد')))}`)}`
  const nameservers = `<div class="xp-whm-detail-fields">${field(v, 'setup-nameserver-1', c('Nameserver 1', 'خادم الأسماء 1'), { value: s?.nameservers[0], disabled: true })}${field(v, 'setup-nameserver-1-address', c('Nameserver 1 address', 'عنوان خادم الأسماء 1'), { disabled: true })}${field(v, 'setup-nameserver-2', c('Nameserver 2', 'خادم الأسماء 2'), { value: s?.nameservers[1], disabled: true })}${field(v, 'setup-nameserver-2-address', c('Nameserver 2 address', 'عنوان خادم الأسماء 2'), { disabled: true })}</div>${status(v, c('Names are read from the saved nameserver list and can be changed in the list above. Nameserver addresses have not been read; address assignment has no connected setup operation.', 'تُقرأ الأسماء من قائمة خوادم الأسماء المحفوظة، ويمكن تعديلها في القائمة أعلاه. لم تُقرأ عناوينها؛ ولا توجد عملية موصولة لتعيين العناوين أثناء الإعداد.'))}`
  const notices = [
    ['setup-notice-config-failure', c('Failed configuration tests and rollbacks', 'فشل فحوص الإعداد والتراجع')],
    ['setup-notice-certificate', c('Certificates that fail to renew', 'الشهادات التي يفشل تجديدها')],
    ['setup-notice-upgrade', c('Upgrade results', 'نتائج الترقية')],
    ['setup-notice-signin', c('Paused sign-ins to xWHM', 'توقّف الدخول إلى xWHM')],
  ] as const
  const nginx = `<h3>${v.text(c('Nginx at the edge', 'Nginx على الحافة'))}</h3><div class="xp-whm-detail-fields">${field(workersView, 'nginx.workerProcesses', c('worker_processes', 'worker_processes'), { value: s?.nginx.workerProcesses, id: 'whm-setup-nginx-workers' })}${field(workersView, 'nginx.workerConnections', c('worker_connections', 'worker_connections'), { value: s?.nginx.workerConnections, type: 'number', id: 'whm-setup-nginx-connections' })}${field(workersView, 'nginx.workerRlimitNofile', c('worker_rlimit_nofile', 'worker_rlimit_nofile'), { value: s?.nginx.workerRlimitNofile, type: 'number', id: 'whm-setup-nginx-nofile' })}${field(workersView, 'nginx.keepaliveTimeoutSec', c('keepalive_timeout (seconds)', 'keepalive_timeout (ثوانٍ)'), { value: s?.nginx.keepaliveTimeoutSec, type: 'number', id: 'whm-setup-nginx-keepalive', help: c('0 disables keepalive. The saved timeout is not a measurement of live connections.', 'تعطّل القيمة 0 الاتصال المستمر. المهلة المحفوظة ليست قياسًا للاتصالات الحية.') })}</div>${choice(workersView, 'nginx.multiAccept', c('multi_accept', 'multi_accept'), s?.nginx.multiAccept)}`
  const apache = `<h3>${v.text(c('Apache mpm-itk', 'Apache mpm-itk'))}</h3><div class="xp-whm-detail-fields">${([['startServers', 'StartServers'], ['minSpareServers', 'MinSpareServers'], ['maxSpareServers', 'MaxSpareServers'], ['maxRequestWorkers', 'MaxRequestWorkers'], ['serverLimit', 'ServerLimit'], ['maxConnectionsPerChild', 'MaxConnectionsPerChild']] as const).map(([key, label]) => field(workersView, `apache.${key}`, c(label, label), { value: s?.apache[key], type: 'number', id: `whm-setup-apache-${key}` })).join('')}</div>${choice(v, 'setup-apache-unlimited', c('Unlimited child lifetime', 'عمر غير محدود للعملية الفرعية'), s ? s.apache.maxConnectionsPerChild === 0 : undefined, true)}<p class="xp-help">${v.text(c('Set MaxConnectionsPerChild to 0 for an unlimited child lifetime; the checkbox reflects the saved value.', 'اضبط MaxConnectionsPerChild على 0 لعمر غير محدود للعملية الفرعية؛ يعكس مربع الاختيار القيمة المحفوظة.'))}</p>`
  const workers = `${!s ? status(v, c('Worker settings have not been read. Reload after the saved server settings are available; no suggested values are assumed.', 'لم تُقرأ إعدادات العمليات. أعد التحميل بعد توافر إعدادات الخادم المحفوظة؛ لا تُفترض قيم مقترحة.')) : ''}${form(workersView, 'server-settings-form', `${nginx}${apache}${actions(save(workersView, c('Save worker settings', 'حفظ إعدادات العمليات')))}`)}${actions(button(v, c('Reset to suggested values', 'إعادة ضبط القيم المقترحة'), '', true))}${status(v, c('The worker form stores only the displayed settings through the existing server-settings operation. It does not establish that a candidate generation was tested or activated.', 'يحفظ نموذج العمليات الإعدادات المعروضة فقط عبر عملية إعدادات الخادم القائمة. ولا يثبت فحص جيل مرشح أو تفعيله.'))}`
  const accountDefaults = `<h3>${v.text(c('Default PHP-FPM pool for new accounts', 'مجمّع PHP-FPM الافتراضي للحسابات الجديدة'))}</h3><div class="xp-whm-detail-fields">${field(v, 'setup-fpm-mode', c('pm', 'pm'), { disabled: true, choices: [['ondemand', c('ondemand', 'ondemand')], ['dynamic', c('dynamic', 'dynamic')], ['static', c('static', 'static')]] })}${field(v, 'setup-fpm-max-children', c('pm.max_children', 'pm.max_children'), { type: 'number', disabled: true })}${field(v, 'setup-fpm-idle-timeout', c('pm.process_idle_timeout', 'pm.process_idle_timeout'), { type: 'number', disabled: true })}${field(v, 'setup-fpm-max-requests', c('pm.max_requests', 'pm.max_requests'), { type: 'number', disabled: true })}</div><h3>${v.text(c('OpenLiteSpeed and lsphp', 'OpenLiteSpeed وlsphp'))}</h3><div class="xp-whm-detail-fields">${field(v, 'setup-lsphp-server-connections', c('Server max connections', 'الحد الأقصى لاتصالات الخادم'), { type: 'number', disabled: true })}${field(v, 'setup-lsphp-account-children', c('lsphp children per account', 'عمليات lsphp لكل حساب'), { type: 'number', disabled: true })}${field(v, 'setup-lsphp-account-connections', c('lsphp connections per account', 'اتصالات lsphp لكل حساب'), { type: 'number', disabled: true })}</div>${status(v, c('Global account defaults for PHP-FPM and lsphp have not been read and have no connected setup write operation. Per-domain PHP settings do not establish these global defaults.', 'لم تُقرأ القيم العامة الافتراضية للحسابات في PHP-FPM وlsphp، ولا توجد عملية موصولة لكتابتها أثناء الإعداد. إعدادات PHP لكل نطاق لا تثبت هذه القيم العامة.'))}`
  return workspace(v, '/whm/server/setup', c('Set up this server', 'إعداد هذا الخادم'), c('Review identity, web engine, worker limits and candidate tests before applying a generation.', 'راجع الهوية ومحرك الويب وحدود العمليات وفحوص المرشح قبل تطبيق جيل.'),
    card(v, 'setup-wizard', c('Server identity and engine', 'هوية الخادم والمحرك'), identity)
    + card(v, 'setup-nameservers', c('Host and nameservers', 'المضيف وخوادم الأسماء'), nameservers)
    + card(v, 'setup-notices', c('Send notices about', 'إرسال إشعارات حول'), notices.map(([name, label]) => choice(v, name, label, undefined, true)).join('') + status(v, c('Notification preferences have not been read and cannot be saved by the setup API. No delivery or always-sent policy is assumed.', 'لم تُقرأ تفضيلات الإشعارات، ولا يمكن حفظها عبر واجهة الإعداد. لا يُفترض إرسال أو تفعيل سياسة إرسال دائمة.')))
    + card(v, 'setup-workers', c('Workers and account defaults', 'العمليات والقيم الافتراضية للحسابات'), workers)
    + card(v, 'setup-account-defaults', c('New account PHP defaults', 'قيم PHP الافتراضية للحسابات الجديدة'), accountDefaults)
    + card(v, 'setup-tests', c('Tests on the candidate generation', 'فحوص الجيل المرشح'), table(v, c('Candidate generation tests', 'فحوص الجيل المرشح'), [c('Check', 'الفحص'), c('Result', 'النتيجة')], [], c('No candidate-generation test result has been returned for this setup request.', 'لم تُرجع نتيجة فحص لجيل مرشح لطلب الإعداد هذا.')) + actions(button(v, c('Apply first generation', 'تطبيق الجيل الأول'), '', true, true) + button(v, c('Back', 'رجوع'), '', true) + button(v, c('Continue', 'متابعة'), '', true))),
    card(v, 'setup-detected', c('Detected on this host', 'المكتشف على المضيف'), facts(v, [[c('Hostname', 'اسم المضيف'), v.props.hostname], [c('Engine', 'المحرك'), v.props.hostSample?.engine], [c('System', 'النظام'), v.props.hostSample?.system], [c('Kernel', 'النواة'), v.props.hostSample?.kernel]]) + `<p>${v.text(c('Repository plans and saved metadata do not prove that packages, quotas or isolation are active on this host.', 'لا تثبت خطط المستودع والبيانات المحفوظة أن الحزم أو الحصص أو العزل نشطة على هذا المضيف.'))}</p>` + actions(button(v, c('Detect again', 'إعادة الكشف'), '', true)))
    + card(v, 'setup-handler-map', c('PHP handlers by engine', 'معالجات PHP حسب المحرك'), table(v, c('PHP handler compatibility', 'توافق معالجات PHP'), [c('Engine', 'المحرك'), c('Handlers', 'المعالجات'), c('Availability', 'التوافر')], [['Apache + mpm-itk', 'PHP-FPM, CGI / suexec', v.text(unavailable)], ['OpenLiteSpeed', 'lsphp', v.text(unavailable)]])))
}

const transfer = (v: View): string => {
  const pending = { ...v, readOnly: true }
  const source = `<ol class="xp-whm-detail-steps">${[c('Connect', 'الاتصال'), c('Accounts', 'الحسابات'), c('Review', 'المراجعة'), c('Transfer', 'النقل')].map((step, i) => `<li><strong>${i + 1}</strong>${v.text(step)}</li>`).join('')}</ol>${actions(button(pending, c('Change source', 'تغيير المصدر')))}${form(pending, 'whm-transfer-form', `<div class="xp-whm-detail-fields">${field(pending, 'sourceHost', c('Source host', 'مضيف المصدر'))}${field(pending, 'sourcePort', c('SSH or API port', 'منفذ SSH أو API'), { type: 'number' })}</div><h3>${v.text(c('Authentication', 'المصادقة'))}</h3><div class="xp-whm-detail-choice-grid">${[['ssh-key', c('SSH key', 'مفتاح SSH')], ['api-token', c('API token', 'رمز API')]].map(([raw, label]) => `<label class="xp-whm-detail-choice"><input type="radio" name="transfer-auth-mode" value="${raw}" disabled><span>${v.text(label as Copy)}</span></label>`).join('')}</div>${field(pending, 'transfer-key-file', c('Key on this server', 'المفتاح على هذا الخادم'))}${actions(button(pending, c('Copy public key', 'نسخ المفتاح العام')))}${field(pending, 'transfer-api-token', c('API token from the source', 'رمز API من المصدر'), { type: 'password' })}${field(pending, 'accountNames', c('Accounts to transfer', 'الحسابات المطلوب نقلها'), { type: 'textarea' })}${actions(button(pending, c('Test connection', 'اختبار الاتصال')) + button(pending, c('Check transfer request', 'فحص طلب النقل'), 'data-action="start-transfer"', false, true))}`)}${status(v, c('The current lifecycle API records and reviews transfer state. It does not connect to a remote source or prove that account data has been copied. Connection, credentials and discovery remain unavailable here.', 'تسجل واجهة دورة الحياة الحالية حالة النقل وتراجعها. ولا تتصل بمصدر بعيد أو تثبت نسخ بيانات الحسابات. يبقى الاتصال وبيانات الدخول والاكتشاف غير متاحة هنا.'))}`
  const conflicts = `${table(v, c('Source accounts and conflicts', 'حسابات المصدر والتعارضات'), [c('Selected', 'محدد'), c('Username', 'اسم المستخدم'), c('Domain', 'النطاق'), c('Plan', 'الخطة'), c('Disk', 'القرص'), c('Databases', 'قواعد البيانات'), c('Mailboxes', 'صناديق البريد'), c('Conflict', 'التعارض'), c('Resolution', 'المعالجة')], [])}<div class="xp-whm-detail-fields">${field(pending, 'transfer-conflict-account', c('Account with a conflict', 'الحساب ذو التعارض'), { choices: [] })}${field(pending, 'transfer-conflict-resolution', c('Resolve conflict', 'معالجة التعارض'), { choices: [['skip', c('Skip account', 'تجاوز الحساب')], ['rename', c('Rename before transfer', 'إعادة التسمية قبل النقل')], ['replace-reviewed', c('Replace after reviewed backup', 'الاستبدال بعد نسخة مراجعة')]] })}</div>${status(v, c('Source inventory and destination conflict checks have not been read. No account selection or replacement is assumed.', 'لم يُقرأ جرد المصدر أو فحص تعارضات الوجهة. لا يُفترض اختيار حساب أو استبداله.'))}`
  const progress = `<div data-transfer-progress-state="not-read">${status(v, c('No native transfer job or per-account progress has been read.', 'لم تُقرأ مهمة نقل أصلية أو نسبة تقدم لكل حساب.'))}</div>${table(v, c('Transfer progress', 'تقدم النقل'), [c('Account', 'الحساب'), c('Files', 'الملفات'), c('Databases', 'قواعد البيانات'), c('Mail', 'البريد'), c('DNS', 'DNS'), c('State', 'الحالة')], [])}${actions(button(pending, c('Back', 'رجوع')) + button(pending, c('Stop after the current account', 'الإيقاف بعد الحساب الحالي')) + button(pending, c('Start transfer', 'بدء النقل'), '', false, true))}`
  const imported = `${field(pending, 'cpanel-backup', c('Backup file', 'ملف النسخة الاحتياطية'), { type: 'file' })}${actions(button(pending, c('Preview import', 'معاينة الاستيراد')))}<h3>${v.text(c('Parsed plan', 'الخطة المقروءة'))}</h3><div class="xp-whm-detail-fields">${field(pending, 'cpanel-plan', c('Plan here', 'الخطة هنا'), { choices: (v.props.plans ?? []).map(plan => [plan.name, c(plan.name, plan.name)] as const) })}${field(pending, 'cpanel-owner', c('Owner', 'المالك'), { choices: (v.props.resellers ?? []).map(reseller => [reseller.username, c(reseller.username, reseller.username)] as const) })}</div>${[c('Domains', 'النطاقات'), c('Home files', 'ملفات المنزل'), c('Databases and users', 'قواعد البيانات والمستخدمون'), c('Mailboxes and filters', 'صناديق البريد والفلاتر'), c('DNS records', 'سجلات DNS')].map((title, i) => `<details><summary>${v.text(title)}</summary>${table(v, title, [c('Item', 'العنصر'), c('Source', 'المصدر'), c('Destination', 'الوجهة'), c('Action', 'الإجراء')], [])}</details>`).join('')}<h3>${v.text(c('Not imported or changed', 'غير المستورد أو المعدّل'))}</h3>${table(v, c('Import exclusions and warnings', 'استثناءات الاستيراد وتنبيهاته'), [c('Item', 'العنصر'), c('Reason', 'السبب'), c('Path', 'المسار')], [])}${status(v, c('The native cPanel archive import adapter is not connected. No archive was parsed or uploaded. Passwords, account identities, owners and paths must be reviewed from a real import plan before any mutation.', 'محول استيراد أرشيف cPanel الأصلي غير موصول. لم يُحلّل أرشيف أو يُرفع. يجب مراجعة كلمات المرور وهويات الحسابات والملاك والمسارات من خطة استيراد فعلية قبل أي تعديل.'))}${actions(button(pending, c('Discard upload', 'تجاهل الملف المرفوع')) + button(pending, c('Import selected account', 'استيراد الحساب المحدد'), '', false, true))}`
  return workspace(v, '/whm/transfers', c('Transfer tool', 'أداة النقل'), c('Review source identity, discovered accounts, conflicts and the import plan before moving data.', 'راجع هوية المصدر والحسابات المكتشفة والتعارضات وخطة الاستيراد قبل نقل البيانات.'), card(v, 'transfer-source', c('Transfer from an xPanel server', 'النقل من خادم xPanel'), source) + card(v, 'transfer-identities', c('Accounts on the source', 'الحسابات على المصدر'), conflicts) + card(v, 'transfer-progress', c('Transfer progress', 'تقدم النقل'), progress) + card(v, 'transfer-import', c('Import a cPanel backup', 'استيراد نسخة cPanel'), imported), card(v, 'transfer-plans', c('Plans used by the selected accounts', 'خطط الحسابات المختارة'), table(v, c('Source plan review', 'مراجعة خطط المصدر'), [c('Source plan', 'خطة المصدر'), c('Destination plan', 'خطة الوجهة'), c('Owner', 'المالك'), c('Conflict', 'التعارض')], []) + status(v, c('Source plans have not been discovered. Names, limits and ownership must be reviewed before import.', 'لم تُكتشف خطط المصدر. يجب مراجعة الأسماء والحدود والملكية قبل الاستيراد.'))))
}

const upgrade = (v: View): string => {
  const pending = { ...v, readOnly: true }
  const release = facts(v, [[c('Installed', 'المثبت'), v.props.version], [c('Available', 'المتاح'), v.props.availableVersion]]) + field(pending, 'targetRelease', c('Target release', 'الإصدار المستهدف'), { value: v.props.availableVersion }) + `<h3>${v.text(c('What changes', 'ما الذي يتغيّر'))}</h3>${status(v, c('Authenticated release notes and schema migrations for the available version have not been read. Prototype release notes are not used as current evidence.', 'لم تُقرأ ملاحظات الإصدار المصادق عليها أو ترحيلات المخطط للإصدار المتاح. لا تُستخدم ملاحظات النموذج بوصفها دليلًا حاليًا.'))}${actions(button(pending, c('Run preflight again', 'إعادة تشغيل الفحص المسبق'), 'data-action="start-upgrade"') + button(pending, c('Upgrade to selected release', 'الترقية إلى الإصدار المحدد'), '', false, true))}<details><summary>${v.text(c('Confirm upgrade', 'تأكيد الترقية'))}</summary>${facts(v, [[c('Server', 'الخادم'), v.props.hostname], [c('From version', 'من الإصدار'), v.props.version], [c('To version', 'إلى الإصدار'), v.props.availableVersion]])}${choice(pending, 'upgrade-confirm-backup', c('A compatible recovery backup has been verified for this release', 'تأكدت نسخة استرجاع متوافقة لهذا الإصدار'), undefined)}${actions(button(pending, c('Cancel', 'إلغاء')) + button(pending, c('Start upgrade', 'بدء الترقية'), '', false, true))}</details>${status(v, c('The lifecycle endpoint records metadata and preflight state; native release staging, migration and activation are not connected to these controls. No switch has started.', 'تسجل واجهة دورة الحياة البيانات الوصفية وحالة الفحص المسبق؛ ولا ترتبط بهذه الأدوات تهيئة إصدار أو ترحيل أو تفعيل فعلي. لم يبدأ أي تبديل.'))}`
  return workspace(v, '/whm/server/upgrade', c('Upgrade', 'الترقية'), c('Review the release, preflight and recovery plan before any version switch.', 'راجع الإصدار والفحص وخطة الاسترجاع قبل أي تبديل للنسخة.'),
    card(v, 'upgrade-version', c('Release', 'الإصدار'), release)
    + card(v, 'upgrade-preflight', c('Preflight', 'الفحص المسبق'), table(v, c('Preflight checks', 'فحوص ما قبل الترقية'), [c('Check', 'الفحص'), c('Result', 'النتيجة')], [[v.text(c('Authenticated artifact and source', 'الأرشيف والمصدر المصادق عليهما')), v.text(unavailable)], [v.text(c('Consistent state and database backup', 'نسخة متسقة للحالة وقاعدة البيانات')), v.text(unavailable)], [v.text(c('Schema compatibility', 'توافق المخطط')), v.text(unavailable)], [v.text(c('Space and runtime prerequisites', 'المساحة ومتطلبات التشغيل')), v.text(unavailable)]]))
    + card(v, 'upgrade-job', c('Upgrade job and progress', 'مهمة الترقية وتقدمها'), `<div data-upgrade-progress-state="not-read">${status(v, c('No native upgrade job or progress observation has been read.', 'لم تُقرأ مهمة ترقية أصلية أو ملاحظة لتقدمها.'))}</div>${table(v, c('Upgrade progress', 'تقدم الترقية'), [c('Phase', 'المرحلة'), c('State', 'الحالة'), c('Result', 'النتيجة')], [])}${actions(button(pending, c('Cancel pending upgrade', 'إلغاء الترقية المعلقة')))}`)
    + card(v, 'upgrade-history', c('Upgrade history', 'سجل الترقية'), table(v, c('Upgrade history', 'سجل الترقية'), [c('From → to', 'من ← إلى'), c('Schema', 'المخطط'), c('Started (UTC)', 'البداية (UTC)'), c('Result', 'النتيجة'), c('Actor', 'المنفذ'), c('Reason', 'السبب')], []) + `<a class="xp-btn" href="/whm/audit?lang=${v.ar ? 'ar' : 'en'}">${v.text(c('All entries in the audit log', 'جميع الإدخالات في سجل التدقيق'))}</a>`),
    card(v, 'upgrade-touches', c('What an upgrade touches', 'ما الذي تغيّره الترقية'), `<h3>${v.text(c('Never touched', 'لا تُمسّ'))}</h3><p>${v.text(c('Account identities, tenant homes, mail and database data must be preserved by the reviewed migration contract.', 'يجب حفظ هويات الحسابات ومجلداتها والبريد وبيانات قواعد البيانات وفق عقد الترحيل المراجع.'))}</p><h3>${v.text(c('Kept as they are', 'المحفوظة كما هي'))}</h3><p>${v.text(c('The prior code, protected settings, identity secrets and compatible control database must be retained together for recovery.', 'يجب حفظ الشفرة السابقة والإعدادات المحمية وأسرار الهوية وقاعدة التحكم المتوافقة معًا للاسترجاع.'))}</p><h3>${v.text(c('Added', 'المضاف'))}</h3>${status(v, c('Release folders, schema additions and generated configuration for this release have not been read. No new release files or schema changes are claimed.', 'لم تُقرأ مجلدات الإصدار أو إضافات المخطط أو الإعدادات المولّدة لهذا الإصدار. لا يُدّعى إنشاء ملفات إصدار أو تعديل مخطط.'))}`)
    + card(v, 'upgrade-health', c('Health check after the switch', 'فحص الصحة بعد التبديل'), status(v, c('No switch has been requested from this page. A metadata preflight is not a deployment receipt.', 'لم يُطلب تبديل من هذه الصفحة. الفحص المسبق للبيانات ليس إيصال نشر.')))
    + card(v, 'upgrade-phases', c('How the upgrade runs', 'كيفية تنفيذ الترقية'), `<ol class="xp-whm-detail-steps">${[c('Precheck', 'الفحص'), c('Snapshot', 'النسخة'), c('Stage', 'التحضير'), c('Migrate', 'الترحيل'), c('Switch', 'التبديل'), c('Health', 'الصحة')].map((step, i) => `<li><strong>${i + 1}</strong>${v.text(step)}</li>`).join('')}</ol>`))
}

const dnsComponents = (v: View): string => {
  const pending = { ...v, readOnly: true }
  const provider = v.props.services?.find(service => /^(?:pdns|powerdns)$/i.test(service.name))
  const checkedProvider = provider?.checked !== false ? provider : undefined
  return card(v, 'dns-zone-list', c('Zones', 'المناطق'), `<span class="xp-help" data-whm-dns-zone-count role="status">${v.text(unavailable)}</span>${table(v, c('DNS zones', 'مناطق DNS'), [c('Zone', 'المنطقة'), c('Account', 'الحساب'), c('Records', 'السجلات'), c('Serial', 'التسلسل'), c('Provider state', 'حالة المزود')], []).replace('<tbody>', '<tbody data-whm-dns-zone-rows>')}${actions(button(pending, c('Previous', 'السابق')) + button(pending, c('Next', 'التالي')))}`) + card(v, 'dns-zone-file', c('Zone file', 'ملف المنطقة'), `${actions(button(pending, c('Import BIND zone', 'استيراد منطقة BIND')) + button(pending, c('Export zone file', 'تصدير ملف المنطقة')))}${field(pending, 'dns-import-file', c('BIND zone file', 'ملف منطقة BIND'), { type: 'file' })}${field(pending, 'dns-import-text', c('BIND zone contents', 'محتوى منطقة BIND'), { type: 'textarea' })}${table(v, c('Zone import differences', 'فروق استيراد المنطقة'), [c('Name', 'الاسم'), c('Type', 'النوع'), c('Current', 'الحالي'), c('Imported', 'المستورد'), c('Action', 'الإجراء')], [])}${actions(button(pending, c('Cancel', 'إلغاء')) + button(pending, c('Preview changes', 'معاينة التغييرات'), '', false, true))}${status(v, c('The existing zone editor remains connected to its DNS API. A BIND parser, difference review and zone-file serializer are not connected here; no file was imported or exported.', 'يبقى محرر المناطق القائم موصولًا بواجهة DNS. لا يرتبط بهذه الأدوات محلل BIND أو مراجعة الفروق أو مولّد ملفات المناطق؛ لم يُستورد ملف أو يُصدّر.'))}`)
    + card(v, 'dns-soa', c('SOA serial', 'تسلسل SOA'), facts(v, [[c('Selected zone serial', 'تسلسل المنطقة المحددة'), undefined], [c('Next serial', 'التسلسل التالي'), undefined]]).replace('<dd>', '<dd data-whm-dns-soa-serial>') + status(v, c('The serial is shown only after an authorized zone read. Serial policy and the next value have not been read; this display never generates a serial.', 'يظهر التسلسل بعد قراءة منطقة مصرّح بها فقط. لم تُقرأ سياسة التسلسل أو القيمة التالية؛ ولا تُولّد هذه الواجهة تسلسلًا.')))
    + card(v, 'dns-history', c('Zone change history', 'سجل تغييرات المنطقة'), table(v, c('Zone history', 'سجل المنطقة'), [c('When (UTC)', 'الوقت (UTC)'), c('Actor', 'المنفذ'), c('Zone', 'المنطقة'), c('Change', 'التغيير'), c('Serial', 'التسلسل'), c('Result', 'النتيجة')], []) + `<a class="xp-btn" href="/whm/audit?lang=${v.ar ? 'ar' : 'en'}">${v.text(c('Open audit log', 'فتح سجل التدقيق'))}</a>`)
    + card(v, 'dns-provider-health', c('PowerDNS API', 'واجهة PowerDNS'), facts(v, [[c('Observed service', 'الخدمة المرصودة'), checkedProvider?.name], [c('Service state', 'حالة الخدمة'), checkedProvider ? v.text(checkedProvider.active ? c('Running', 'تعمل') : c('Stopped', 'متوقفة')) : undefined], [c('API connectivity', 'اتصال الواجهة'), undefined], [c('Last successful zone write', 'آخر كتابة ناجحة لمنطقة'), undefined]]) + actions(button(pending, c('Check again', 'الفحص مجددًا'))) + status(v, c('A service observation is not proof of API connectivity or zone propagation. Provider health, pending writes and retry results have not been read.', 'لا تثبت ملاحظة الخدمة اتصال الواجهة أو انتشار المنطقة. لم تُقرأ صحة المزود أو الكتابات المعلقة أو نتائج إعادة المحاولة.')))
}

/** Appended to the real DNS editor: no duplicate page heading or native mutation controls. */
export const renderWhmDnsSupplement = (input: DetailProps): string => {
  const principal = input.visibility?.principal ?? input.principal
  const acls = input.visibility?.reseller?.acl ?? input.activeReseller?.acl ?? []
  if (input.capabilityUnavailable || !(principal?.kind === 'root' || principal?.kind === 'reseller' && acls.includes('manage-dns'))) return ''
  const ar = input.locale === 'ar'
  const v: View = { props: input, ar, readOnly: true, root: principal.kind === 'root', text: copy => escapeHtml(copy[ar ? 1 : 0]) }
  return `${styles}<section class="xp-whm-detail" data-approved-whm-dns-supplement>${dnsComponents(v)}</section>`
}

