/** Full workspace structure survives unavailable host capabilities without exposing private records. */
export const renderWhmDetailPage = (input: DetailProps): string | undefined => {
  const route = input.activeRoute ?? '/whm'
  if (input.capabilityUnavailable && ['/whm/accounts', '/whm/accounts/new', '/whm/plans', '/whm/security/firewall', '/whm/services'].includes(route)) {
    const safe: DetailProps = { activeRoute: route, locale: input.locale, capabilityUnavailable: true }
    const ar = input.locale === 'ar'
    const v: View = { props: safe, ar, readOnly: true, root: false, text: copy => escapeHtml(copy[ar ? 1 : 0]) }
    const accountList = card(v, 'account-list-unavailable', c('Accounts', 'الحسابات'), `<div class="xp-whm-detail-fields">${field(v, 'pending-account-search', c('Search accounts', 'البحث في الحسابات'))}${field(v, 'pending-account-owner', c('Owner', 'المالك'), { choices: [] })}${field(v, 'pending-account-plan', c('Plan', 'الخطة'), { choices: [] })}${field(v, 'pending-account-status', c('Status', 'الحالة'), { choices: [['active', c('Active', 'نشط')], ['suspended', c('Suspended', 'معلق')]] })}</div>${table(v, c('Accounts', 'الحسابات'), [c('Select', 'اختيار'), c('Account', 'الحساب'), c('Domain', 'النطاق'), c('Owner', 'المالك'), c('IP', 'IP'), c('Plan', 'الخطة'), c('Disk', 'القرص'), c('Bandwidth', 'نقل البيانات'), c('Status', 'الحالة'), c('Actions', 'الإجراءات')], [])}${actions(button(v, c('Previous', 'السابق')) + button(v, c('Next', 'التالي')))}`)
    const creation = card(v, 'account-create-unavailable', c('Account identity and plan', 'هوية الحساب والخطة'), `<div class="xp-whm-detail-fields">${field(v, 'username', c('Username', 'اسم المستخدم'), { id: 'new-acc-username' })}${field(v, 'primaryDomain', c('Primary domain', 'النطاق الأساسي'), { id: 'new-acc-domain' })}${field(v, 'contactEmail', c('Contact email', 'بريد التواصل'), { id: 'new-acc-contact', type: 'email' })}${field(v, 'planId', c('Hosting plan', 'خطة الاستضافة'), { id: 'new-acc-plan', choices: [] })}${field(v, 'password', c('Password', 'كلمة المرور'), { id: 'new-acc-password', type: 'password' })}${field(v, 'ipAssignment', c('IPv4 assignment', 'تعيين IPv4'), { id: 'new-acc-ipv4', choices: [] })}${field(v, 'ipv6', c('IPv6 address (optional)', 'عنوان IPv6 (اختياري)'), { id: 'new-acc-ipv6' })}</div>${renderApprovedWhmAccountCreateFields(safe)}${table(v, c('Selected plan capacity', 'سعة الخطة المحددة'), [c('Resource', 'المورد'), c('Plan', 'الخطة'), c('After creation', 'بعد الإنشاء'), c('State', 'الحالة')], [])}${actions(button(v, c('Create account', 'إنشاء حساب'), '', true, true))}`)
    const planList = card(v, 'plans-unavailable', c('Hosting plans', 'خطط الاستضافة'), table(v, c('Hosting plans', 'خطط الاستضافة'), [c('Plan', 'الخطة'), c('Disk / Bandwidth', 'القرص / نقل البيانات'), c('CPU / Memory', 'المعالج / الذاكرة'), c('Disk read / write', 'قراءة / كتابة القرص'), c('Processes', 'العمليات'), c('Addon domains', 'النطاقات الإضافية'), c('Shell', 'الطرفية'), c('Actions', 'الإجراءات')], []) + actions(button(v, c('Create plan', 'إنشاء خطة'))))
    const planEditor = card(v, 'plan-editor-unavailable', c('Plan editor', 'محرر الخطط'), `<div class="xp-whm-detail-fields">${field(v, 'pending-plan-name', c('Plan name', 'اسم الخطة'))}${field(v, 'pending-plan-features', c('Feature list', 'قائمة الميزات'), { choices: [] })}</div><h3>${v.text(c('Resources', 'الموارد'))}</h3><div class="xp-whm-detail-fields">${PLAN_RESOURCE_FIELDS.map(item => field(v, `pending-plan-${item.key}`, item.label, { type: 'number' }) + choice(v, `pending-plan-unlimited-${item.key}`, c('Unlimited', 'غير محدود'), undefined)).join('')}</div><h3>${v.text(c('Service limits', 'حدود الخدمات'))}</h3><div class="xp-whm-detail-fields">${PLAN_CAP_FIELDS.map(item => field(v, `pending-plan-${item.key}`, item.label, { type: 'number' }) + choice(v, `pending-plan-unlimited-${item.key}`, c('Unlimited', 'غير محدود'), undefined)).join('')}${field(v, 'pending-plan-mailbox-quota', PLAN_QUOTA_FIELD.label, { type: 'number' })}${field(v, 'pending-plan-shell', c('Shell access', 'الوصول إلى الطرفية'), { choices: [['none', c('No shell', 'بدون طرفية')], ['jailed', c('Jailed shell', 'طرفية معزولة')]] })}</div>${actions(button(v, c('Save plan', 'حفظ الخطة'), '', true, true))}`)
    const services = card(v, 'managed-services-unavailable', c('Managed services', 'الخدمات المُدارة'), table(v, c('Managed services', 'الخدمات المُدارة'), [c('Service', 'الخدمة'), c('Unit', 'الوحدة'), c('Version', 'الإصدار'), c('State', 'الحالة'), c('Memory', 'الذاكرة'), c('Action', 'الإجراء')], []) + actions(button(v, c('Reload service', 'إعادة تحميل الخدمة')) + button(v, c('Restart service', 'إعادة تشغيل الخدمة'))))
    const content = route === '/whm/accounts/new' ? creation + renderApprovedWhmAccountCreateStatus(safe)
      : route === '/whm/accounts' ? renderApprovedWhmAccountBulkControls(safe) + accountList
      : route === '/whm/plans' ? planList + planEditor + renderApprovedWhmPlanSupplement(safe)
      : route === '/whm/services' ? services + renderApprovedWhmOperationsSupplement(safe) : renderApprovedWhmOperationsSupplement(safe)
    const title = route === '/whm/accounts/new' ? c('Create account', 'إنشاء حساب') : route === '/whm/accounts' ? c('Accounts', 'الحسابات') : route === '/whm/plans' ? c('Plans', 'الخطط') : route === '/whm/services' ? c('Services', 'الخدمات') : c('Firewall', 'الجدار الناري')
    return workspace(v, route, title, c('Approved components remain visible while the host operation is unavailable.', 'تبقى المكونات المعتمدة ظاهرة أثناء عدم توافر عملية المضيف.'), content)
  }
  if (input.capabilityUnavailable && route === '/whm/dns') {
    const ar = input.locale === 'ar'
    const v: View = { props: {}, ar, readOnly: true, root: false, text: copy => escapeHtml(copy[ar ? 1 : 0]) }
    const editor = card(v, 'dns-editor-unavailable', c('Zones and records', 'المناطق والسجلات'), table(v, c('Zones', 'المناطق'), [c('Zone', 'المنطقة'), c('Account', 'الحساب'), c('Records', 'السجلات'), c('Serial', 'التسلسل'), c('State', 'الحالة')], []) + `<div class="xp-whm-detail-fields">${field(v, 'dns-pending-zone', c('Zone', 'المنطقة'), { choices: [] })}${field(v, 'dns-pending-account', c('Account', 'الحساب'), { choices: [] })}${field(v, 'dns-pending-new-zone', c('New zone name', 'اسم منطقة جديدة'))}</div>${table(v, c('Records in the selected zone', 'سجلات المنطقة المحددة'), [c('Name', 'الاسم'), c('Type', 'النوع'), c('TTL', 'TTL'), c('Content', 'المحتوى'), c('Priority', 'الأولوية')], [])}${actions(button(v, c('Add zone', 'إضافة منطقة')) + button(v, c('Edit records', 'تحرير السجلات')) + button(v, c('Save zone', 'حفظ المنطقة')) + button(v, c('Delete zone', 'حذف المنطقة')))}`)
    const record = card(v, 'dns-record-unavailable', c('Add a record', 'إضافة سجل'), `<div class="xp-whm-detail-fields">${field(v, 'dns-pending-record-type', c('Record type', 'نوع السجل'), { choices: ['A', 'AAAA', 'CNAME', 'MX', 'TXT', 'SRV', 'CAA'].map(type => [type, c(type, type)] as const) })}${field(v, 'dns-pending-record-name', c('Name', 'الاسم'))}${field(v, 'dns-pending-record-ttl', c('TTL', 'TTL'), { type: 'number' })}${field(v, 'dns-pending-record-content', c('Content', 'المحتوى'))}${field(v, 'dns-pending-record-priority', c('Priority', 'الأولوية'), { type: 'number' })}${field(v, 'dns-pending-record-weight', c('Weight', 'الوزن'), { type: 'number' })}${field(v, 'dns-pending-record-port', c('Port', 'المنفذ'), { type: 'number' })}</div>${actions(button(v, c('Clear', 'مسح')) + button(v, c('Add record', 'إضافة سجل')))}`)
    return workspace(v, route, c('DNS zones', 'مناطق DNS'), c('Zone files, SOA, history and provider health remain visible until this host qualifies DNS operations.', 'تبقى ملفات المناطق وSOA والسجل وصحة المزود ظاهرة إلى أن يؤهّل المضيف عمليات DNS.'), editor + record + dnsComponents(v))
  }
  if (input.capabilityUnavailable && ['/whm/backups', '/whm/backups/restore'].includes(route)) return renderApprovedWhmBackups({ activeRoute: route, locale: input.locale, capabilityUnavailable: true })
  if (input.capabilityUnavailable && ['/whm/resellers', '/whm/resellers/privileges'].includes(route)) return renderApprovedWhmResellers({ activeRoute: route, locale: input.locale, capabilityUnavailable: true })
  const page = detailPages[route]
  if (!page) return undefined
  const ar = input.locale === 'ar'
  const text = (copy: Copy): string => escapeHtml(copy[ar ? 1 : 0])
  const principal = input.visibility?.principal ?? input.principal
  const acls = input.visibility?.reseller?.acl ?? input.activeReseller?.acl ?? []
  const authorized = principal?.kind === 'root' || (principal?.kind === 'reseller' && page.acl !== undefined && acls.includes(page.acl))
  if (!input.capabilityUnavailable && !authorized) return `<section class="xp-card" data-whm-detail-denied role="status"><h1>${text(page.title)}</h1><p>${text(c('This workspace requires an authorized administrator context.', 'تتطلب هذه الواجهة سياق مدير مصرّحًا به.'))}</p></section>`
  const operationId = route === '/whm/plans/features' ? 'feature-list-crud'
    : ['/whm/services/web', '/whm/security/ssh', '/whm/server/setup'].includes(route) ? 'server-settings-edit' : undefined
  const missingOperation = operationId !== undefined && !input.catalog?.some(tool => tool.id === operationId && tool.status === 'verified')
  const readOnly = input.capabilityUnavailable === true || missingOperation
  // A document availability fallback receives only route/locale. Ignore any accidental private DTOs.
  const props: DetailProps = readOnly ? { activeRoute: route, locale: input.locale, capabilityUnavailable: true } : input
  return page.render({ props, ar, readOnly, root: principal?.kind === 'root', text })
}


/** Exports contain only the authorized page and public labels, never internal audit keys or raw details. */
export const renderWhmAuditExports = (props: WhmSurfaceProps): string => {
  const locale = props.locale ?? 'en'
  const rows = (props.auditEntries ?? []).map(entry => ({
    at: entry.at,
    actor: auditActorLabel(entry.actor),
    action: auditActionLabel(entry.action, locale, entry),
    target: auditTargetLabel(entry.target, locale),
    outcome: auditOutcomeLabel(entry.action, entry.outcome, locale),
  }))
  const csvCell = (raw: string): string => {
    const safe = /^[=+@\-\t\r]/.test(raw) ? `'${raw}` : raw
    return `"${safe.replaceAll('"', '""')}"`
  }
  const csv = [['UTC', 'Actor', 'Action', 'Target', 'Outcome'], ...rows.map(row => [row.at, row.actor, row.action, row.target, row.outcome])].map(row => row.map(csvCell).join(',')).join('\r\n')
  const csvHref = `data:text/csv;charset=utf-8,${encodeURIComponent('\uFEFF' + csv).replaceAll("'", '%27')}`
  const jsonHref = `data:application/json;charset=utf-8,${encodeURIComponent(JSON.stringify(rows, null, 2)).replaceAll("'", '%27')}`
  return `<div class="xp-whm-detail-actions" data-audit-export><a class="xp-btn" download="xpanel-audit-page.csv" href="${escapeHtml(csvHref)}">${locale === 'ar' ? 'تصدير الصفحة CSV' : 'Export page CSV'}</a><a class="xp-btn" download="xpanel-audit-page.json" href="${escapeHtml(jsonHref)}">${locale === 'ar' ? 'تصدير الصفحة JSON' : 'Export page JSON'}</a></div>`
}

export const renderWhmAuditSupplement = (props: WhmSurfaceProps): string => {
  const ar = props.locale === 'ar'
  const v: View = { props, ar, readOnly: true, root: true, text: copy => escapeHtml(copy[ar ? 1 : 0]) }
  const entries = props.auditEntries ?? []
  const detail = entries.map(entry => `<details data-audit-entry-detail><summary>${escapeHtml(auditActionLabel(entry.action, props.locale ?? 'en', entry))} · ${renderLtrValue(formatAsciiDate(entry.at, { includeTime: true }))}</summary>${facts(v, [[c('Actor', 'الفاعل'), auditActorLabel(entry.actor)], [c('Target', 'الهدف'), auditTargetLabel(entry.target, props.locale ?? 'en')], [c('Outcome', 'النتيجة'), auditOutcomeLabel(entry.action, entry.outcome, props.locale ?? 'en')]])}</details>`).join('')
  return `${styles}<div class="xp-whm-detail-grid" data-audit-supplement><div class="xp-whm-detail-column">${card(v, 'audit-recorded-entry', c('Recorded entry', 'المدخل المسجل'), detail || status(v, c('No entries match the current page.', 'لا توجد مدخلات في الصفحة الحالية.')))}</div><aside class="xp-whm-detail-column">${card(v, 'audit-config-generations', c('Config generations', 'أجيال الإعدادات'), generationTable(v))}<p class="xp-help">${v.text(c('Exports and details contain this authorized page only. Older entries use the keyset page links.', 'يحتوي التصدير والتفاصيل على هذه الصفحة المصرّح بها فقط. تستعمل المدخلات الأقدم روابط صفحات المؤشر.'))}</p></aside></div>`
}
